rh<-function(v){h<-floor(nrow(v)/2);v<-cbind(v[1:h,,drop=FALSE],v[(nrow(v)-h+1):nrow(v),,drop=FALSE]);W<-mean(apply(v,2,var));B<-nrow(v)*var(colMeans(v));sqrt(((nrow(v)-1)/nrow(v)*W+B/nrow(v))/W)}
for(db in c('MIMIC','eICU','SICdb')){x<-readRDS(paste0('Z:/Research/MSI-1/results/V331_MAR_MNAR敏感性_G3/V331_',db,'_MICE20_G3.rds'));it<-x$iteration;z<-sapply(dimnames(x$chainMean)[[1]],function(v){a<-x$chainMean[v,,];if(anyNA(a))return(c(mean=NA,sd=NA));c(mean=rh(a[(floor(it/2)+1):it,]),sd=rh(sqrt(x$chainVar[v,(floor(it/2)+1):it,])))});cat(db,it,'\n');print(head(sort(z[1,],decreasing=TRUE),5));print(head(sort(z[2,],decreasing=TRUE),5))}
